+        if (surface?.dataset.dailyCapture === 'true' && selectedSign?.value) {
+          const radios = Array.from(form.querySelectorAll<HTMLInputElement>('input[name="sign"]'));
+          radios.forEach((input) => { input.defaultChecked = input === selectedSign; });
+          surface.dataset.personalizedSign = 'true';
+        }
+        form.reset();
+        if (surface?.dataset.dailyCapture === 'true' && selectedSign?.value) {
+          renderCaptureSign(surface, selectedSign, true);
+        }
+        const placement = form.dataset.placement ?? 'unknown';
+        (window as AnalyticsWindow)
+          .zodiacsAnalytics?.track?.('email_subscribed', { placement });
+      } catch {
+        status.textContent = form.querySelector<HTMLElement>('[data-error-copy]')?.textContent ?? '';
+      } finally {
+        button.disabled = false;
+        button.textContent = idle;
+      }
+    });
+  });
+</script>

