+                </span>
+                <EvidenceDisclosure label={t(locale, 'howWeCompute')}>
+                  <span class="mono mp__meta mp__meta--faint">{formatLongitude(result.lon, locale)}</span>
+                  {result.caption !== '' && result.altLon === null && <p>{result.caption}</p>}
