+          </div>
+          {result.altLon !== null && (
+            <p class="notice" role="status">
+              {t(locale, 'moonChangedNotice')}
+            </p>
+          )}
+          <div class="calc__actions">
+            <a class="btn btn--ghost" href={localizePath(locale, '/birth-chart/')}>
+              <span>{t(locale, 'birthChartForDate')}</span><span class="orb">↗</span>
+            </a>
+          </div>
+        </div>
+      )}
+    </div>
+  );
+}

