+<script>
+  type AnalyticsWindow = Window & {
+    zodiacsAnalytics?: { track?: (name: string, props: Record<string, string>) => void };
+  };
+  // These generations own presentation only. A submitted subscription still
+  // completes once; an obsolete response must not reset a replacement form.
+  const captureGenerations = new WeakMap<HTMLElement, number>();
+  const captureGeneration = (surface: HTMLElement | null) => surface
+    ? captureGenerations.get(surface) ?? 0
+    : 0;
+
+  function advanceCapture(surface: HTMLElement) {
+    captureGenerations.set(surface, captureGeneration(surface) + 1);
+    const button = surface.querySelector<HTMLButtonElement>('button[type="submit"]');
+    const status = surface.querySelector<HTMLElement>('[data-email-status]');
+    if (button) {
+      button.disabled = false;
+      button.textContent = button.dataset.label ?? button.textContent;
+    }
+    if (status) status.textContent = '';
+  }
+
+  function trackCaptureView(surface: HTMLElement) {
+    if (surface.dataset.viewTracked === 'true') return;
+    surface.dataset.viewTracked = 'true';
+    (window as AnalyticsWindow).zodiacsAnalytics?.track?.('email_capture_viewed', {
+      placement: surface.dataset.placement ?? 'unknown',
+    });
+  }
+
+  const captureSurfaces = document.querySelectorAll<HTMLElement>('[data-email-capture-shell]');
+  if ('IntersectionObserver' in window) {
+    const captureObserver = new IntersectionObserver((entries, observer) => {
+      entries.forEach((entry) => {
+        if (!entry.isIntersecting) return;
+        trackCaptureView(entry.target as HTMLElement);
+        observer.unobserve(entry.target);
+      });
+    }, { threshold: 0.2 });
+    captureSurfaces.forEach((surface) => captureObserver.observe(surface));
+  } else {
+    captureSurfaces.forEach((surface) => {
+      if (!surface.hidden) trackCaptureView(surface);
+    });
+  }
+
+  function preselectCaptureSign(surface: HTMLElement, sign: string | undefined) {
+    if (!sign) return;
