+  window.addEventListener('zodiacs:chart-context-cleared', () => {
+    document.querySelectorAll<HTMLElement>('[data-reveal-on-chart="true"]').forEach((surface) => {
+      advanceCapture(surface);
+      surface.hidden = true;
+    });
+  });
+
+  captureSurfaces.forEach(setupSignChooser);
+
+  document.querySelectorAll<HTMLFormElement>('[data-email-capture]').forEach((form) => {
+    if (form.dataset.enhanced === 'true') return;
+    form.dataset.enhanced = 'true';
+    form.addEventListener('reset', () => {
+      const surface = form.closest<HTMLElement>('[data-email-capture-shell]');
+      const generation = captureGeneration(surface);
+      queueMicrotask(() => {
+        if (!surface || !surface.isConnected || generation !== captureGeneration(surface)
+          || surface.dataset.personalizedSign !== 'true') return;
+        const selected = form.querySelector<HTMLInputElement>('input[name="sign"]:checked');
+        renderCaptureSign(surface, selected ?? undefined, Boolean(selected?.value));
+      });
+    });
+    form.addEventListener('submit', async (event) => {
+      event.preventDefault();
+      const button = form.querySelector<HTMLButtonElement>('button[type="submit"]');
+      const status = form.querySelector<HTMLElement>('[data-email-status]');
+      if (!button || !status) return;
+      const email = form.querySelector<HTMLInputElement>('input[name="email"]');
+      const selectedSign = form.querySelector<HTMLInputElement>('input[name="sign"]:checked');
+      const surface = form.closest<HTMLElement>('[data-email-capture-shell]');
+      const generation = captureGeneration(surface);
+      const requestIsCurrent = () => form.isConnected
+        && generation === captureGeneration(surface);
+      if (!email?.validity.valid) {
