+      } catch {
+        if (requestIsCurrent()) status.textContent = form.querySelector<HTMLElement>('[data-error-copy]')?.textContent ?? '';
+      } finally {
+        if (requestIsCurrent()) {
+          button.disabled = false;
+          button.textContent = idle;
+        }
+      }
+    });
+  });
+</script>

