+    <div class="field">
+      <label class="field__label" for={placeId}>{t(locale, 'birthplace')}</label>
+      <PlaceSearch
+        id={placeId}
+        selected={city}
+        onSelect={onCityChange}
+        locale={locale}
+        validationError={placeError}
+        selectionHint={t(locale, 'placePickHint')}
+        required
+      />
+      {placeHelp !== undefined && <p class="field__help">{placeHelp}</p>}
+    </div>,
+  ];
