+export const CONTEXT_CONVENTION = 'zodiacs-chart-context-v1';
+export const SHAPE_BODIES = ['Sun', 'Moon', 'Mercury', 'Venus', 'Mars', 'Jupiter', 'Saturn', 'Uranus', 'Neptune', 'Pluto'] as const;
