+  const ia = SIGN_SLUGS.indexOf(a);
+  const ib = SIGN_SLUGS.indexOf(b);
+  if (ia < 0 || ib < 0) throw new Error(`Unknown sign in pair: ${a}, ${b}`);
+  return ia <= ib ? `${a}-${b}` : `${b}-${a}`;
