+/** Kept separate so client-side path helpers do not carry head-only metadata. */
+export const LOCALE_PATH_PREFIX = {
+  en: '',
+  es: '/es',
+  pt: '/pt',
+  fr: '/fr',
+  it: '/it',
+  ru: '/ru',
+  ar: '/ar',
+} as const satisfies Record<Locale, string>;
