+  return locale === 'en';
+}
+
+const CORE_LOCALIZED_PATHS = [
+  '/',
+  '/tools/',
+  '/birth-chart/',
+  '/compatibility/',
+  '/moon-sign/',
+  '/rising-sign/',
+  '/moon-phase/',
+  '/saturn-return/',
+  '/transits/',
+  '/baby-zodiac/',
+  '/profile/',
+  '/methodology/',
+  '/privacy/',
+  '/disclosure/',
