+const POSITIONS_VERSION_PREFIX = '2.';
+const POSITION_DECIMAL_FACTOR = 1e3;
+const POSITIONS_TOKEN_MAX_LENGTH = 256;
+const ENGINE_VERSION_MAX_LENGTH = 32;
+const ENGINE_VERSION_RE = /^[A-Za-z0-9][A-Za-z0-9._+-]{0,31}$/;
